"""QR codes, generated by the application (CM-8).

One generator for every code the arc prints or shows: the per-card code on a
postcard (the campaign's link plus the card's own token), and any link's code on
the Links tab. No external service — the same code whoever prints the next
batch. ``segno`` is a pure-Python encoder with no dependencies of its own and
writes PNG through the standard library, so the image needs no Pillow.
"""

from __future__ import annotations

import io

import segno


def qr_png(data: str, *, scale: int = 8, border: int = 2) -> bytes:
    """A PNG of ``data`` as a QR code. Error correction M, the vendor templates'
    usual level; ``scale`` is pixels per module."""
    code = segno.make(data, error="m")
    out = io.BytesIO()
    code.save(out, kind="png", scale=scale, border=border)
    return out.getvalue()


def qr_svg(data: str, *, scale: int = 6, border: int = 2) -> str:
    """The same code as inline SVG, for a preview that scales."""
    code = segno.make(data, error="m")
    out = io.BytesIO()
    code.save(out, kind="svg", scale=scale, border=border, xmldecl=False, svgns=True)
    return out.getvalue().decode("utf-8")
